export default function(c) {
  c.addFilter("jsonScript", v => JSON.stringify(v ?? null).replace(/[<>&\u2028\u2029]/g, ch => "\\u" + ch.charCodeAt(0).toString(16).padStart(4, "0")));
  return { dir: { input: "content", includes: "_includes", output: "_site" }, markdownTemplateEngine: "njk" };
}
